-- Errata reading for G13: Index discharges limited to those at least 30 days before the as-of date (complete follow-up window), as C10/D14 do.
WITH acute AS MATERIALIZED ( SELECT patient, json_extract(payload,'$.encounter_id') AS enc, event AS d FROM records WHERE stream='adt' AND json_extract(payload,'$.event') IN ('admission','emergency_registration','observation_start') ), dis AS MATERIALIZED ( SELECT patient, json_extract(payload,'$.encounter_id') AS enc, event AS d FROM records WHERE stream='adt' AND json_extract(payload,'$.event')='discharge' ) SELECT ROUND(100.0 * SUM(EXISTS (SELECT 1 FROM acute a WHERE a.patient=dis.patient AND a.enc<>dis.enc AND julianday(a.d)-julianday(dis.d) BETWEEN 1 AND 30)) / COUNT(*), 4) AS value FROM dis WHERE d <= date(:as_of,'-30 days');
